        std::pair<RT::Point, RT::Weight> p1 = rt.point(h, i);
        std::pair<RT::Point, RT::Weight> p2 = rt.point(h, j);
        RT::Point pt1 = p1.first;
        RT::Point pt2 = p2.first;
        double squared_length = (pt1.x() - pt2.x()) * (pt1.x() - pt2.x()) +
                                (pt1.y() - pt2.y()) * (pt1.y() - pt2.y()) +
                                (pt1.z() - pt2.z()) * (pt1.z() - pt2.z());
        if (squared_length > threshold) {
            ++count;
        }
    }
}
return count;

